import json, os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.request import urlopen, Request

ENGINE_URL = os.getenv('ENGINE_URL', 'https://binance-30s-engine.onrender.com').rstrip('/')

HTML = r'''<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cryptoalpha Control Dashboard</title>
<style>
:root{--bg:#070a0f;--panel:#0e141d;--panel2:#111925;--line:#202b3a;--text:#edf3fb;--muted:#8492a6;--good:#27d17f;--warn:#f4b740;--bad:#ff5d6c;--blue:#5aa7ff}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 80% -10%,#17243a 0,#070a0f 42%);color:var(--text);font:14px Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.wrap{max-width:1380px;margin:auto;padding:14px}.top{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:12px}.brand{font-size:22px;font-weight:850}.sub{color:var(--muted);font-size:11px;margin-top:3px}.actions{display:flex;gap:7px;flex-wrap:wrap}.btn,.select{background:#0c121b;color:var(--text);border:1px solid var(--line);border-radius:9px;padding:8px 10px;font-size:12px}.btn{cursor:pointer}.btn:hover{border-color:#45617f}.pill{border:1px solid #244b3b;background:#0d2119;color:#69e6a6;border-radius:999px;padding:8px 12px;font-weight:750;font-size:11px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.grid3{display:grid;grid-template-columns:1.25fr .9fr .9fr;gap:9px;margin-top:9px}.card{background:linear-gradient(180deg,var(--panel2),var(--panel));border:1px solid var(--line);border-radius:13px;padding:13px;box-shadow:0 10px 25px #0003}.label{font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:var(--muted)}.value{font-size:23px;font-weight:850;margin-top:5px}.delta{font-size:11px;margin-top:3px}.good{color:var(--good)}.warn{color:var(--warn)}.bad{color:var(--bad)}.blue{color:var(--blue)}.section{font-weight:800;margin-bottom:9px}.row{display:flex;justify-content:space-between;gap:8px;align-items:center}.mini{font-size:11px;color:var(--muted)}.meter{height:7px;background:#18212d;border-radius:8px;overflow:hidden;margin-top:10px}.fill{height:100%;width:0;background:linear-gradient(90deg,#27d17f,#5aa7ff)}.tableWrap{overflow:auto;max-height:390px}table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:8px;border-bottom:1px solid var(--line);text-align:left;font-size:11px}th{color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.06em;position:sticky;top:0;background:#111925}.tag{display:inline-flex;border:1px solid #2a384b;border-radius:6px;padding:3px 6px;color:#cbd7e7;background:#0b1119}.status{display:grid;grid-template-columns:1fr 1fr;gap:7px}.statusItem{background:#0a1017;border:1px solid var(--line);padding:9px;border-radius:9px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--good);margin-right:5px}.dot.off{background:var(--bad)}canvas{width:100%;height:145px;display:block}.tabs{display:flex;gap:6px;margin:9px 0}.tab{padding:7px 10px;border-radius:8px;border:1px solid var(--line);color:var(--muted);cursor:pointer}.tab.active{color:var(--text);border-color:#3b5877;background:#111c2b}.hidden{display:none}.footer{color:var(--muted);font-size:10px;margin-top:8px}.mono{font-variant-numeric:tabular-nums}@media(max-width:900px){.grid{grid-template-columns:repeat(2,1fr)}.grid3{grid-template-columns:1fr 1fr}}@media(max-width:600px){.grid,.grid3{grid-template-columns:1fr}.top{align-items:flex-start}.brand{font-size:19px}.actions{margin-top:7px}}
</style></head><body><div class="wrap">
<div class="top"><div><div class="brand">Cryptoalpha Control Dashboard</div><div class="sub">Real-time telemetry · paper execution · Binance Spot + USDT-M Futures</div></div><div class="actions"><button class="btn" id="pause">Pause updates</button><button class="btn" id="reset">Reset view</button><span class="pill">● PAPER ONLY · LIVE OFF</span></div></div>
<div class="grid">
<div class="card"><div class="label">Equity</div><div class="value mono" id="equity">$10.000000</div><div class="delta good" id="pnl">+$0.000000</div></div>
<div class="card"><div class="label">Compounded return</div><div class="value mono" id="ret">0.0000%</div><div class="delta" id="dd">Drawdown 0.00%</div></div>
<div class="card"><div class="label">Qualified opportunities</div><div class="value mono" id="opps">0</div><div class="delta" id="split">Spot 0 · Futures 0</div></div>
<div class="card"><div class="label">Paper entries</div><div class="value mono" id="entries">0</div><div class="delta" id="wl">Wins 0 · Losses 0</div></div>
</div>
<div class="grid3">
<div class="card"><div class="row"><div><div class="section">Equity monitor</div><div class="mini" id="chartMeta">Waiting for telemetry…</div></div><span class="tag" id="rate">1s</span></div><canvas id="chart"></canvas></div>
<div class="card"><div class="section">Best opportunities</div><div class="label">Spot triangular</div><div class="value" id="bestSpot">—</div><div class="delta" id="spotMeta">—</div><div class="meter"><div class="fill" id="spotFill"></div></div><div class="label" style="margin-top:12px">Futures basis</div><div class="value" id="bestFut">—</div><div class="delta" id="futMeta">—</div></div>
<div class="card"><div class="section">Connection health</div><div class="status"><div class="statusItem"><span class="dot" id="sd"></span>Spot WS <b id="sw">0/0</b></div><div class="statusItem"><span class="dot" id="fd"></span>Futures WS <b id="fw">0/0</b></div><div class="statusItem">Spot updates <b id="su">0</b></div><div class="statusItem">Futures updates <b id="fu">0</b></div></div><div class="footer" id="health">Connecting…</div></div>
</div>
<div class="tabs"><button class="tab active" data-tab="oppsTab">Opportunities</button><button class="tab" data-tab="systemTab">System</button></div>
<div id="oppsTab" class="card"><div class="row"><div class="section">Live opportunity tape</div><select id="filter" class="select"><option value="ALL">All engines</option><option value="SPOT_TRIANGULAR">Spot triangular</option><option value="SPOT_FUTURES_BASIS">Spot/Futures basis</option></select></div><div class="tableWrap"><table><thead><tr><th>Engine</th><th>Market / Path</th><th>Direction</th><th>Gross</th><th>Net</th><th>Notional</th></tr></thead><tbody id="rows"><tr><td colspan="6">Waiting for telemetry…</td></tr></tbody></table></div></div>
<div id="systemTab" class="hidden"><div class="grid3" style="margin-top:0"><div class="card"><div class="section">Engine configuration</div><div class="status"><div class="statusItem">Min net <b id="minNet">—</b></div><div class="statusItem">Risk <b id="risk">—</b></div><div class="statusItem">Symbols <b id="symbols">—</b></div><div class="statusItem">Routes <b id="routes">—</b></div></div></div><div class="card"><div class="section">Runtime</div><div id="runtime">—</div><div class="footer" id="err">Errors: 0</div></div><div class="card"><div class="section">Execution safety</div><div class="statusItem">Mode <b class="good">PAPER ONLY</b></div><div class="statusItem" style="margin-top:7px">Live execution <b class="bad">OFF</b></div><div class="statusItem" style="margin-top:7px">Unsupported <b id="unsupported">—</b></div></div></div></div>
<div class="footer">Auto-refresh every 1 second. “Reset view” clears only this browser's chart/filter state; it does not alter engine equity.</div>
</div>
<script>
const $=id=>document.getElementById(id), money=x=>'$'+Number(x||0).toFixed(6), num=(x,d=2)=>Number(x||0).toFixed(d);
let paused=false, history=[], latest=null;
function draw(){const c=$('chart'),ctx=c.getContext('2d'),w=c.clientWidth*devicePixelRatio,h=145*devicePixelRatio;c.width=w;c.height=h;ctx.clearRect(0,0,w,h);if(history.length<2)return;const vals=history.map(x=>x.e),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1;ctx.beginPath();history.forEach((p,i)=>{const x=i/(history.length-1)*w,y=h-((p.e-min)/span)*(h-12)-6;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.strokeStyle='#5aa7ff';ctx.lineWidth=2*devicePixelRatio;ctx.stroke();ctx.fillStyle='#8492a6';ctx.font=(10*devicePixelRatio)+'px system-ui';ctx.fillText('min '+money(min),6,h-4);ctx.fillText('max '+money(max),w-105,h-4)}
function render(d){latest=d;setText('equity',money(d.equity));setText('pnl',(d.paper_pnl>=0?'+':'')+money(d.paper_pnl));setText('ret',num(d.compound_return_pct,4)+'%');setText('dd','Drawdown '+num(d.drawdown_pct,2)+'%');const total=(d.spot_opportunities||0)+(d.futures_opportunities||0);setText('opps',total);setText('split','Spot '+(d.spot_opportunities||0)+' · Futures '+(d.futures_opportunities||0));setText('entries',d.paper_entries||0);setText('wl','Wins '+(d.wins||0)+' · Losses '+(d.losses||0));setText('sw',(d.spot_sockets_up||0)+'/'+(d.spot_sockets||0));setText('fw',(d.futures_sockets_up||0)+'/'+(d.futures_sockets||0));setText('su',d.quote_updates_spot||0);setText('fu',d.quote_updates_futures||0);$('sd').className='dot '+(d.ws_spot?'':'off');$('fd').className='dot '+(d.ws_futures?'':'off');setText('health',(d.ws_spot?'Spot connected':'Spot reconnecting')+' · '+(d.ws_futures?'Futures connected':'Futures reconnecting')+' · errors '+(d.errors||0));const s=d.best_spot,f=d.best_futures;setText('bestSpot',s?((s.path||s.symbol)+' · '+num(s.net_bps)+' bps'):'No qualified setup');setText('spotMeta',s?'Gross '+num(s.gross_bps)+' bps · '+money(s.notional_usdt):'—');$('spotFill').style.width=Math.min(100,Math.max(2,(s?s.net_bps:0)*4))+'%';setText('bestFut',f?(f.symbol+' · '+num(f.net_bps)+' bps'):'No qualified setup');setText('futMeta',f?(f.direction+' · basis '+num(f.basis_bps)+' bps'):'—');setText('minNet',num(d.min_net_bps)+' bps');setText('risk',num(d.risk_pct,3)+'%');setText('symbols',(d.spot_symbols||0)+' spot / '+(d.futures_symbols||0)+' futures');setText('routes',d.triangular_routes||0);setText('runtime',(d.halted?'HALTED':'RUNNING')+' · '+num(d.uptime_seconds,0)+'s · '+num(d.scans,0)+' scans');setText('err','Errors: '+(d.errors||0)+(d.last_error?' · '+d.last_error:''));setText('unsupported',(d.unsupported_engines||[]).join(', ')||'None');history.push({t:Date.now(),e:Number(d.equity||0)});if(history.length>120)history.shift();setText('chartMeta','Last update '+new Date().toLocaleTimeString()+' · '+history.length+' samples');draw();renderRows(d)}
function renderRows(d){const f=$('filter').value;let rows=(d.top_opportunities||[]).filter(x=>f==='ALL'||x.engine===f).slice(0,50);$('rows').innerHTML=rows.map(x=>'<tr><td><span class="tag">'+(x.engine||'—')+'</span></td><td>'+((x.path||x.symbol)||'—')+'</td><td>'+(x.direction||'—')+'</td><td>'+num(x.gross_bps)+' bps</td><td class="good">'+num(x.net_bps)+' bps</td><td>'+money(x.notional_usdt)+'</td></tr>').join('')||'<tr><td colspan="6">No qualified opportunities</td></tr>'}
function setText(id,v){$(id).textContent=v}
async function refresh(){if(paused)return;try{const t=Date.now(),r=await fetch('/api/stats?ts='+t,{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);render(await r.json());$('rate').textContent='1s'}catch(e){setText('health','Dashboard connection error: '+e.message);$('rate').textContent='error'}}
$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'Resume updates':'Pause updates'};$('reset').onclick=()=>{history=[];localStorage.removeItem('cryptoalpha_filter');draw();setText('chartMeta','View reset — waiting for telemetry…');$('filter').value='ALL'};$('filter').onchange=()=>{localStorage.setItem('cryptoalpha_filter',$('filter').value);if(latest)renderRows(latest)};const saved=localStorage.getItem('cryptoalpha_filter');if(saved)$('filter').value=saved;document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('#oppsTab,#systemTab').forEach(x=>x.classList.add('hidden'));b.classList.add('active');$(b.dataset.tab).classList.remove('hidden')});window.onresize=draw;refresh();setInterval(refresh,1000);
</script></body></html>'''

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path.startswith('/api/stats'):
            try:
                req=Request(ENGINE_URL+'/stats.json',headers={'User-Agent':'Cryptoalpha-Dashboard/2.0'})
                with urlopen(req,timeout=5) as r: body=r.read()
                self.send_response(200);self.send_header('Content-Type','application/json');self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(body)
            except Exception as e:
                body=json.dumps({'error':str(e)}).encode();self.send_response(502);self.send_header('Content-Type','application/json');self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(body)
            return
        body=HTML.encode();self.send_response(200);self.send_header('Content-Type','text/html; charset=utf-8');self.send_header('Cache-Control','no-store');self.end_headers();self.wfile.write(body)
    def log_message(self,*args): pass

if __name__=='__main__':
    ThreadingHTTPServer(('0.0.0.0',int(os.getenv('PORT','10000'))),Handler).serve_forever()
